oxy_webhelp_navlinks = {"arch_monitor_locations-d39536e9393":{"topics":[{"title":"Viewing the Archival Locations page","shortdesc":"<p class=\"shortdesc\">View the Archival Locations page to create and manage archival locations. You can         also view the details and manage settings for each location.<\/p>","href":"archival\/arch_viewing_arch_loc_page.html","attributes":{"data-id":"arch_viewing_arch_loc_page"},"menu":{"hasChildren":false},"tocID":"arch_viewing_arch_loc_page-d39536e9406","topics":[]},{"title":"Data center archival location filters","shortdesc":"<p class=\"shortdesc\">You can filter archival locations based on various criteria in <span class=\"ph\">RSC<\/span>.<\/p>","href":"archival\/arch_dc_archival_location_filters.html","attributes":{"data-id":"arch_dc_archival_location_filters"},"menu":{"hasChildren":false},"tocID":"arch_dc_archival_location_filters-d39536e9417","topics":[]},{"title":"Data center archival location details","shortdesc":"<p class=\"shortdesc\">The Data Center Archival Locations page provides information about each archival         location associated with the account in the Locations tab. Additionally, you can monitor the         archival throughput for all the archival locations from the Performance tab.<\/p>","href":"archival\/arch_dc_arch_loc_details.html","attributes":{"data-id":"arch_dc_arch_loc_details"},"menu":{"hasChildren":false},"tocID":"arch_dc_arch_loc_details-d39536e9431","topics":[]},{"title":"Resolving harmful lifecycle policy alerts","shortdesc":"<p class=\"shortdesc\">If <span class=\"ph\">RSC<\/span> detects lifecycle policies configured outside Rubrik on a data         center archival location, an alert banner appears on the Data Center Archival Locations         page. These policies can cause recovery failures or data loss. Delete the detected policies         from your cloud provider account to restore archival operations.<\/p>","href":"archival\/resolving_lifecycle_policy_alerts.html","attributes":{"data-id":"resolving_lifecycle_policy_alerts"},"menu":{"hasChildren":false},"tocID":"resolving_lifecycle_policy_alerts-d39536e9442","topics":[]},{"title":"Viewing the archival locations dashboard","shortdesc":"<p class=\"shortdesc\">View the archival locations dashboard for enhanced visibility into your data center         archival locations. You can monitor information such as storage growth over time,         archival lag, and detailed storage consumption breakdown by protected workloads at each         location.<\/p>","href":"saas\/arch_viewing_arch_loc_dashboard.html","attributes":{"data-id":"arch_viewing_arch_loc_dashboard"},"menu":{"hasChildren":false},"tocID":"arch_viewing_arch_loc_dashboard-d39536e9456","next":"arch_viewing_arch_loc_dashboard-d39536e9456"},{"title":"Monitoring archival jobs","shortdesc":"<p class=\"shortdesc\">Monitor archival job status in <span class=\"ph\">RSC<\/span> to verify that workloads are         being archived as configured and to identify failures that require attention.<\/p>","href":"archival\/arch_monitoring_archival_jobs.html","attributes":{"data-id":"arch_monitoring_archival_jobs"},"menu":{"hasChildren":false},"tocID":"arch_monitoring_archival_jobs-d39536e9491","topics":[]}]}};